import * as React from 'react';
import { describe, it, expect, afterEach } from 'vitest';
import { render, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
afterEach(cleanup);

describe('focused latch', () => {
  it('unmount while focused', () => {
    function App({ show }: { show: boolean }) {
      return <Field.Root data-testid="root">{show ? <Field.Control /> : null}</Field.Root>;
    }
    const { rerender } = render(<App show />);
    const root = screen.getByTestId('root');
    const input = screen.getByRole('textbox') as HTMLInputElement;
    act(() => { input.focus(); });
    expect(document.activeElement).toBe(input);
    expect(root.hasAttribute('data-focused')).toBe(true);
    rerender(<App show={false} />);
    console.log('after unmount: data-focused present=%o activeElement=%o', root.hasAttribute('data-focused'), document.activeElement?.tagName);
    expect(root.hasAttribute('data-focused')).toBe(false);
  });

  it('disabled while focused', () => {
    function App({ disabled }: { disabled: boolean }) {
      return <Field.Root data-testid="root"><Field.Control disabled={disabled} /></Field.Root>;
    }
    const { rerender } = render(<App disabled={false} />);
    const root = screen.getByTestId('root');
    const input = screen.getByRole('textbox') as HTMLInputElement;
    act(() => { input.focus(); });
    expect(root.hasAttribute('data-focused')).toBe(true);
    rerender(<App disabled />);
    console.log('after disabled: data-focused present=%o input.disabled=%o activeElement=%o', root.hasAttribute('data-focused'), input.disabled, document.activeElement?.tagName);
    expect(root.hasAttribute('data-focused')).toBe(false);
  });
});

describe('filled on controlled remount', () => {
  it('keyed remount with empty controlled value under persistent Field.Root', () => {
    const { rerender } = render(
      <Field.Root data-testid="root"><Field.Control key="a" value="abc" onValueChange={() => {}} /></Field.Root>,
    );
    const root = screen.getByTestId('root');
    expect(root.hasAttribute('data-filled')).toBe(true);
    rerender(
      <Field.Root data-testid="root"><Field.Control key="b" value="" onValueChange={() => {}} /></Field.Root>,
    );
    const input = screen.getByRole('textbox') as HTMLInputElement;
    console.log('keyed remount: input.value=%o data-filled present=%o', input.value, root.hasAttribute('data-filled'));
    expect(input.value).toBe('');
    expect(root.hasAttribute('data-filled')).toBe(false);
  });
});
EOF
